    handles,labels=axes.flat[0].get_legend_handles_labels();fig.legend(handles,labels,loc='lower center',ncol=2,frameon=False)
    fig.suptitle('Historias completas: la continuidad de importes no rellena campos del riesgo',fontsize=16);fig.tight_layout(rect=[0,.06,1,.95]);fig.savefig(out/'figures/histories.png',dpi=150,bbox_inches='tight');plt.close(fig)
